import axios from "axios";
import { API_BASE_URL, STORAGE_KEYS } from "../constants/AppConstants";

// Single axios instance every service shares, so the backend base URL and
// auth header only need to be configured in one place.
const api = axios.create({
  baseURL: API_BASE_URL,
  headers: { "Content-Type": "application/json" },
  timeout: 8000,
});

api.interceptors.request.use((config) => {
  const raw = localStorage.getItem(STORAGE_KEYS.SESSION);
  if (raw) {
    try {
      const session = JSON.parse(raw);
      if (session?.token) {
        config.headers.Authorization = `Bearer ${session.token}`;
      }
    } catch {
      // corrupt session blob — ignore, request goes out unauthenticated
    }
  }
  return config;
});

export default api;
